-- real_inventory.sql: generated by Backend/scripts/import-inventory.js from
-- Bongalink_Inventory_Final.xlsx. Do not edit by hand; change the workbook and regenerate.
-- 36 products (22 shown, 14 hidden), 30 photos
-- (10 products with photos: 10 covers + 20 gallery rows),
-- 3 renames and 12 products hidden, as approved at the import review.
-- Run it with the mysql client, never with --force: a failed check stops it before COMMIT.
-- Safe to run again: only values that differ are written.

SET NAMES utf8mb4 COLLATE utf8mb4_unicode_ci;   -- the tables' collation (the server default differs), so variables compare with columns
START TRANSACTION;

SET @app_user_id = 4;
SET @import_note = 'Real inventory import (Bongalink_Inventory_Final.xlsx)';
SET @stock_reason = CONCAT('correction: ', @import_note);

-- check: user 4 is an active admin
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT COUNT(*) FROM users WHERE user_id = @app_user_id AND role = 'admin' AND status = 'active') = 1, FALSE));
-- check: category "Printer Parts" exists
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT category_id FROM categories WHERE name = 'Printer Parts') IS NOT NULL, FALSE));
-- check: category "Accessories" exists
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT category_id FROM categories WHERE name = 'Accessories') IS NOT NULL, FALSE));
-- check: the migration 003 and 005 product triggers are installed
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT COUNT(*) FROM information_schema.triggers WHERE trigger_schema = DATABASE() AND trigger_name IN ('trg_products_ml_insert', 'trg_products_ml_update', 'trg_products_history_insert', 'trg_products_history_update', 'trg_product_images_insert', 'trg_product_images_delete')) = 6, FALSE));

-- ---------------------------------------------------------------- renames
-- The same part under another name: keep the row (product_id, sales), rename it.
-- check: product 61 is "Ink Cartridge BH-7" (or already "Cartridge Head BH-7 Black")
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT name FROM products WHERE product_id = 61) IN ('Ink Cartridge BH-7', 'Cartridge Head BH-7 Black'), FALSE));
-- check: no other product is called "Cartridge Head BH-7 Black"
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT COUNT(*) FROM products WHERE name = 'Cartridge Head BH-7 Black' AND product_id <> 61) = 0, FALSE));
SET @app_change_reason = @import_note;
UPDATE products SET name = 'Cartridge Head BH-7 Black' WHERE product_id = 61 AND name = 'Ink Cartridge BH-7';

-- check: product 23 is "CR Motor L1800" (or already "CR Motor L1300/L1800")
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT name FROM products WHERE product_id = 23) IN ('CR Motor L1800', 'CR Motor L1300/L1800'), FALSE));
-- check: no other product is called "CR Motor L1300/L1800"
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT COUNT(*) FROM products WHERE name = 'CR Motor L1300/L1800' AND product_id <> 23) = 0, FALSE));
SET @app_change_reason = @import_note;
UPDATE products SET name = 'CR Motor L1300/L1800' WHERE product_id = 23 AND name = 'CR Motor L1800';

-- check: product 25 is "Printhead 51AA" (or already "Printhead HP M0H51AA Black")
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT name FROM products WHERE product_id = 25) IN ('Printhead 51AA', 'Printhead HP M0H51AA Black'), FALSE));
-- check: no other product is called "Printhead HP M0H51AA Black"
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT COUNT(*) FROM products WHERE name = 'Printhead HP M0H51AA Black' AND product_id <> 25) = 0, FALSE));
SET @app_change_reason = @import_note;
UPDATE products SET name = 'Printhead HP M0H51AA Black' WHERE product_id = 25 AND name = 'Printhead 51AA';

