-- [1/36] Cartridge Head BH-70 Black: stock 3, price 1800.00, shown, 3 photo(s)
SET @app_change_reason = @import_note;
SET @pid = (SELECT product_id FROM products WHERE name = 'Cartridge Head BH-70 Black');
INSERT INTO products (name, category_id, brand, price, stock_quantity, is_active, image_path, description, created_by)
SELECT 'Cartridge Head BH-70 Black', (SELECT category_id FROM categories WHERE name = 'Printer Parts'), 'Canon', 1800.00, 3, 1, '/uploads/cartridge-head-bh-70-black-1.jpg', 'Genuine Canon PIXMA BH-70 black print head, brand new in box. P3,500 when bought as a pair with CH-70.', @app_user_id
  FROM DUAL WHERE @pid IS NULL;
SET @pid = (SELECT product_id FROM products WHERE name = 'Cartridge Head BH-70 Black');
-- check: stock 3 is not below what unpaid orders hold
DO (SELECT 1 FROM (SELECT 1 UNION ALL SELECT 2) g WHERE NOT COALESCE((SELECT reserved FROM products WHERE product_id = @pid) <= 3, FALSE));
SET @app_change_reason = @stock_reason;
INSERT INTO inventory_movements (product_id, change_qty, reason, reference, note, created_by)
SELECT product_id, 3 - CAST(stock_quantity AS SIGNED), 'correction', 'adjustment', @import_note, @app_user_id
  FROM products WHERE product_id = @pid AND stock_quantity <> 3;
UPDATE products SET stock_quantity = 3 WHERE product_id = @pid;
SET @app_change_reason = @import_note;
UPDATE products SET category_id = (SELECT category_id FROM categories WHERE name = 'Printer Parts'), brand = 'Canon', price = 1800.00, is_active = 1,
       image_path = '/uploads/cartridge-head-bh-70-black-1.jpg',
       description = IF(description IS NULL OR TRIM(description) = '' OR description LIKE 'Imported from the 2026 sales sheet%', 'Genuine Canon PIXMA BH-70 black print head, brand new in box. P3,500 when bought as a pair with CH-70.', description)
 WHERE product_id = @pid;
SET @have = (SELECT GROUP_CONCAT(image_path ORDER BY sort_order, image_id SEPARATOR '|') FROM product_images WHERE product_id = @pid);
SET @want = '/uploads/cartridge-head-bh-70-black-2.jpg|/uploads/cartridge-head-bh-70-black-3.jpg';
DELETE FROM product_images WHERE product_id = @pid AND NOT (@have <=> @want);
INSERT INTO product_images (product_id, image_path, sort_order)
SELECT @pid, v.image_path, v.sort_order FROM (SELECT '/uploads/cartridge-head-bh-70-black-2.jpg' AS image_path, 0 AS sort_order UNION ALL SELECT '/uploads/cartridge-head-bh-70-black-3.jpg', 1) v
 WHERE NOT (@have <=> @want);

